// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Copies of the component GUMBO contracts for system-level verification.
//! The originals live in the component crates, which this crate cannot
//! depend on (they are staticlibs); both are generated from the same
//! GUMBO source, so they are identical by construction (TCB item T3).

#![allow(non_snake_case)]

use data::*;
use vstd::prelude::*;

verus! {

// -- seL4_i_Instance.ArduPilot.ArduPilot --
pub mod ap {
  use super::*;

  /** integration assume OnlyPermittedFrames (I-Assm, incoming port EthernetFramesRx)
    */
  pub open spec fn integration_spec_OnlyPermittedFrames_assume(
    api_EthernetFramesRx: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    (api_EthernetFramesRx.is_some()) ==> (((!(GumboLib::isMalformedFrame_spec(api_EthernetFramesRx.unwrap())) && GumboLib::isIPV4_spec(api_EthernetFramesRx.unwrap())) &&
      GumboLib::isTCP_spec(api_EthernetFramesRx.unwrap())) &&
      GumboLib::isPortWhitelisted_spec(api_EthernetFramesRx.unwrap()))
  }

  /** integration guarantee TxOut_IPv4OrARP (I-Guar, outgoing port EthernetFramesTx)
    *   ArduPilot emits only IPv4 or ARP frames.
    */
  pub open spec fn integration_spec_TxOut_IPv4OrARP_guarantee(
    api_EthernetFramesTx: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    (api_EthernetFramesTx.is_some()) ==> (GumboLib::txExpected_spec(api_EthernetFramesTx.unwrap()))
  }
}

// -- seL4_i_Instance.FirewallRx.FirewallRx --
pub mod rx {
  use super::*;

  /** initialize guarantee CR01_Rx_Init
    *   FirewallRx_Req_Init: malformed count starts at zero; attack status DataPort initialized to OK.
    */
  pub open spec fn initialize_CR01_Rx_Init(
    malformedCount: i32,
    api_AttackStatusRx: SW::AttackStatus) -> bool
  {
    (malformedCount == 0i32) &&
      (api_AttackStatusRx == SW::AttackStatus::OK)
  }

  /** compute guarantee RC_INSPECTA_00_HLR_1
    *   1.1 firewall: no frame in RxOut if no frame in RxIn (RC_INSPECTA_00-HLR-1) The firewall shall not have any frame in RxOut if there are no frame in RxIn.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_1_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    !(api_EthernetFramesRxIn.is_some()) ==> api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_2
    *   1.2 firewall: drop malformed frames (RC_INSPECTA_00-HLR-1) The firewall shall drop any frame that is malformed.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_2_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesRxIn.is_some() ==>
      GumboLib::isMalformedFrame_spec(api_EthernetFramesRxIn.unwrap()) ==> api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_4
    *   1.4 firewall: drop ipv6 frames (RC_INSPECTA_00-HLR-2) The firewall shall drop any frame that is type ipv6.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_4_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesRxIn.is_some() ==>
      GumboLib::isIPV6_spec(api_EthernetFramesRxIn.unwrap()) ==> api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_6
    *   1.6 firewall: drop RxIn ipv4 arp frames (RC_INSPECTA_00-HLR-4) The firewall shall drop any frame from RxIn that is an Ipv4 frame whose protocol is ARP.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_6_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesRxIn.is_some() ==>
      GumboLib::isARP_spec(api_EthernetFramesRxIn.unwrap()) ==> api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_8
    *   1.8 firewall: drop RxIn ipv4 tcp frames with unexpected ports (RC_INSPECTA_00-HLR-6) The firewall shall drop any frame from RxIn that is an Ipv4 frame whose protocol is TCP and whose port is not defined in the port whitelist.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_8_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesRxIn.is_some() ==>
      ((GumboLib::isIPV4_spec(api_EthernetFramesRxIn.unwrap()) && GumboLib::isTCP_spec(api_EthernetFramesRxIn.unwrap())) &&
        !(GumboLib::isPortWhitelisted_spec(api_EthernetFramesRxIn.unwrap()))) ==>
        api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_9
    *   1.9 firewall: copy through allowed tcp port packets (RC_INSPECTA_00-HLR-8; revised CR-01: applies in Normal mode only) In Normal mode, the firewall shall copy any frame from RxIn that is a non-malformed Ipv4 frame with the TCP protocol and whose port is defined in the port whitelist to RxOut.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_9_guarantee(
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
    api_CurrentMode: SW::Mode,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesRxIn.is_some() ==>
      (((((api_CurrentMode == SW::Mode::Normal) &&
        GumboLib::isIPV4_spec(api_EthernetFramesRxIn.unwrap())) &&
        GumboLib::isTCP_spec(api_EthernetFramesRxIn.unwrap())) &&
        GumboLib::isPortWhitelisted_spec(api_EthernetFramesRxIn.unwrap())) &&
        !(GumboLib::isMalformedFrame_spec(api_EthernetFramesRxIn.unwrap()))) ==>
        api_EthernetFramesRxOut.is_some() &&
          (api_EthernetFramesRxIn.unwrap() == api_EthernetFramesRxOut.unwrap())
  }

  /** compute guarantee CR01_Rx_ModeGate
    *   FirewallRx_Req_ModeGate (CR-01): in Init and RTL modes, drop every frame — no output regardless of input.
    */
  pub open spec fn compute_spec_CR01_Rx_ModeGate_guarantee(
    api_CurrentMode: SW::Mode,
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    !(api_CurrentMode == SW::Mode::Normal) ==> api_EthernetFramesRxOut.is_none()
  }

  /** compute guarantee CR01_Rx_Count
    *   FirewallRx_Req_Count (CR-01): cumulative malformed-frame count since initialization, incremented on each malformed received frame, saturating at 6; mode-independent.
    */
  pub open spec fn compute_spec_CR01_Rx_Count_guarantee(
    In_malformedCount: i32,
    malformedCount: i32,
    api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    ((api_EthernetFramesRxIn.is_some() && GumboLib::isMalformedFrame_spec(api_EthernetFramesRxIn.unwrap()) &&
      (In_malformedCount < 6i32) ==>
      (malformedCount == In_malformedCount + 1i32)) &&
      (api_EthernetFramesRxIn.is_some() && GumboLib::isMalformedFrame_spec(api_EthernetFramesRxIn.unwrap()) &&
        (In_malformedCount >= 6i32) ==>
        (malformedCount == In_malformedCount))) &&
      (!(api_EthernetFramesRxIn.is_some()) || !(GumboLib::isMalformedFrame_spec(api_EthernetFramesRxIn.unwrap())) ==>
        (malformedCount == In_malformedCount))
  }

  /** compute guarantee CR01_Rx_Detect
    *   FirewallRx_Req_Detect (CR-01): report Attack when the (post-update) malformed count exceeds five, OK otherwise.
    */
  pub open spec fn compute_spec_CR01_Rx_Detect_guarantee(
    malformedCount: i32,
    api_AttackStatusRx: SW::AttackStatus) -> bool
  {
    ((malformedCount > 5i32) ==>
      (api_AttackStatusRx == SW::AttackStatus::Attack)) &&
      ((malformedCount <= 5i32) ==>
        (api_AttackStatusRx == SW::AttackStatus::OK))
  }

  /** integration guarantee RxOut_OnlyPermitted (I-Guar, outgoing port EthernetFramesRxOut)
    *   Only non-malformed, IPv4, TCP frames on a whitelisted port leave the RxFirewall.
    */
  pub open spec fn integration_spec_RxOut_OnlyPermitted_guarantee(
    api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    (api_EthernetFramesRxOut.is_some()) ==> (GumboLib::rxShouldPass_spec(api_EthernetFramesRxOut.unwrap()))
  }
}

// -- seL4_i_Instance.FirewallTx.FirewallTx --
pub mod tx {
  use super::*;

  /** initialize guarantee CR01_Tx_Init
    *   FirewallTx_Req_Init: attack status DataPort initialized to OK.
    */
  pub open spec fn initialize_CR01_Tx_Init(
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    api_AttackStatusTx == SW::AttackStatus::OK
  }

  /** compute guarantee RC_INSPECTA_00_HLR_7
    *   2.1 firewall: copy out TxIn arp frame (RC_INSPECTA_00-HLR-7; revised CR-01: applies in Normal mode only) In Normal mode, if the firewall gets a wellformed Arp frame from TxIn, the firewall shall copy the frame to TxOut.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_7_guarantee(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
    api_CurrentMode: SW::Mode,
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesTxIn.is_some() ==>
      (((api_CurrentMode == SW::Mode::Normal) &&
        !(GumboLib::isMalformedFrame_spec(api_EthernetFramesTxIn.unwrap()))) &&
        GumboLib::isARP_spec(api_EthernetFramesTxIn.unwrap())) ==>
        api_EthernetFramesTxOut.is_some() &&
          (api_EthernetFramesTxIn.unwrap() == api_EthernetFramesTxOut.unwrap())
  }

  /** compute guarantee RC_INSPECTA_00_HLR_12
    *   2.2 firewall: copy out TxIn ipv4 frame (RC_INSPECTA_00-HLR-12; revised CR-01: applies in Normal mode only) In Normal mode, if the firewall gets a wellformed IPv4 frame from TxIn, the firewall shall copy the frame to TxOut.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_12_guarantee(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
    api_CurrentMode: SW::Mode,
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesTxIn.is_some() ==>
      (((api_CurrentMode == SW::Mode::Normal) &&
        !(GumboLib::isMalformedFrame_spec(api_EthernetFramesTxIn.unwrap()))) &&
        GumboLib::isIPV4_spec(api_EthernetFramesTxIn.unwrap())) ==>
        api_EthernetFramesTxOut.is_some() &&
          (api_EthernetFramesTxIn.unwrap() == api_EthernetFramesTxOut.unwrap())
  }

  /** compute guarantee RC_INSPECTA_00_HLR_14
    *   2.3 firewall: do not copy disallowed frame (RC_INSPECTA_00-HLR-14) If the firewall gets a malformed ARP frame or malformed TCP frame, it should drop the frame.
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_14_guarantee(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    api_EthernetFramesTxIn.is_some() ==>
      (!(GumboLib::isIPV4_spec(api_EthernetFramesTxIn.unwrap())) && !(GumboLib::isARP_spec(api_EthernetFramesTxIn.unwrap())) ||
        GumboLib::isMalformedFrame_spec(api_EthernetFramesTxIn.unwrap())) ==>
        api_EthernetFramesTxOut.is_none()
  }

  /** compute guarantee RC_INSPECTA_00_HLR_16
    *   2.4 firewall: no output on empty input (RC_INSPECTA_00-HLR-16) If the firewall gets no input on TxIn, it should produce no output on TxOut
    */
  pub open spec fn compute_spec_RC_INSPECTA_00_HLR_16_guarantee(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    !(api_EthernetFramesTxIn.is_some()) ==> api_EthernetFramesTxOut.is_none()
  }

  /** compute guarantee CR01_Tx_ModeGate
    *   FirewallTx_Req_ModeGate (CR-01): in Init and RTL modes, drop every frame — no output regardless of input.
    */
  pub open spec fn compute_spec_CR01_Tx_ModeGate_guarantee(
    api_CurrentMode: SW::Mode,
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    !(api_CurrentMode == SW::Mode::Normal) ==> api_EthernetFramesTxOut.is_none()
  }

  /** compute guarantee CR01_Tx_Detect
    *   FirewallTx_Req_Detect (CR-01): report Attack on any dispatch whose received frame carries the mocked geofence violation (rawMessage byte 0 == 0), OK on every other dispatch; mode-independent, per-dispatch (no latch — persistence is the ModeManager's RTL).
    */
  pub open spec fn compute_spec_CR01_Tx_Detect_guarantee(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    (api_EthernetFramesTxIn.is_some() && GumboLib::isGeofenceViolation_spec(api_EthernetFramesTxIn.unwrap()) ==>
      (api_AttackStatusTx == SW::AttackStatus::Attack)) &&
      (!(api_EthernetFramesTxIn.is_some()) || !(GumboLib::isGeofenceViolation_spec(api_EthernetFramesTxIn.unwrap())) ==>
        (api_AttackStatusTx == SW::AttackStatus::OK))
  }

  /** integration assume TxIn_IPv4OrARP (I-Assm, incoming port EthernetFramesTxIn)
    *   The TxFirewall receives only IPv4 or ARP frames.
    */
  pub open spec fn integration_spec_TxIn_IPv4OrARP_assume(
    api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    (api_EthernetFramesTxIn.is_some()) ==> (GumboLib::txExpected_spec(api_EthernetFramesTxIn.unwrap()))
  }

  /** integration guarantee TxOut_OnlyPermitted (I-Guar, outgoing port EthernetFramesTxOut)
    *   Only non-malformed IPv4 or ARP frames leave the TxFirewall.
    */
  pub open spec fn integration_spec_TxOut_OnlyPermitted_guarantee(
    api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
  {
    (api_EthernetFramesTxOut.is_some()) ==> (!(GumboLib::isMalformedFrame_spec(api_EthernetFramesTxOut.unwrap())) && GumboLib::txExpected_spec(api_EthernetFramesTxOut.unwrap()))
  }
}

// -- seL4_i_Instance.ModeManager.ModeManager --
pub mod mm {
  use super::*;

  /** initialize guarantee CR01_MM_Init
    *   ModeManager_Req_Init: start in Init with zero activations; mode DataPort initialized to Init.
    */
  pub open spec fn initialize_CR01_MM_Init(
    activationCount: i32,
    currentMode: SW::Mode,
    api_CurrentMode: SW::Mode) -> bool
  {
    ((currentMode == SW::Mode::Init) &&
      (activationCount == 0i32)) &&
      (api_CurrentMode == SW::Mode::Init)
  }

  /** compute guarantee CR01_MM_Count
    *   ModeManager_Req_Count: activation counter increments each dispatch, saturating at 10.
    */
  pub open spec fn compute_spec_CR01_MM_Count_guarantee(
    In_activationCount: i32,
    activationCount: i32) -> bool
  {
    ((In_activationCount < 10i32) ==>
      (activationCount == In_activationCount + 1i32)) &&
      ((In_activationCount >= 10i32) ==>
        (activationCount == In_activationCount))
  }

  /** compute guarantee CR01_MM_Absorbing
    *   ModeManager_Req_Absorbing: RTL is absorbing until restart (RD-3).
    */
  pub open spec fn compute_spec_CR01_MM_Absorbing_guarantee(
    In_currentMode: SW::Mode,
    currentMode: SW::Mode) -> bool
  {
    (In_currentMode == SW::Mode::RTL) ==>
      (currentMode == SW::Mode::RTL)
  }

  /** compute guarantee CR01_MM_ToRTL
    *   ModeManager_Req_ToRTL: when not already in RTL and either firewall reports Attack, enter RTL (wins ties against Init-to-Normal).
    */
  pub open spec fn compute_spec_CR01_MM_ToRTL_guarantee(
    In_currentMode: SW::Mode,
    currentMode: SW::Mode,
    api_AttackStatusRx: SW::AttackStatus,
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    (!(In_currentMode == SW::Mode::RTL) &&
      (GumboLib::isAttack_spec(api_AttackStatusRx) || GumboLib::isAttack_spec(api_AttackStatusTx))) ==>
      (currentMode == SW::Mode::RTL)
  }

  /** compute guarantee CR01_MM_StayInit
    *   ModeManager_Req_StayInit: in Init with no attack and (post-increment) count below 10, remain in Init.
    */
  pub open spec fn compute_spec_CR01_MM_StayInit_guarantee(
    In_currentMode: SW::Mode,
    activationCount: i32,
    currentMode: SW::Mode,
    api_AttackStatusRx: SW::AttackStatus,
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    (((In_currentMode == SW::Mode::Init) &&
      !(GumboLib::isAttack_spec(api_AttackStatusRx) || GumboLib::isAttack_spec(api_AttackStatusTx))) &&
      (activationCount < 10i32)) ==>
      (currentMode == SW::Mode::Init)
  }

  /** compute guarantee CR01_MM_ToNormal
    *   ModeManager_Req_ToNormal: in Init with no attack and (post-increment) count reaching 10, transition to Normal.
    */
  pub open spec fn compute_spec_CR01_MM_ToNormal_guarantee(
    In_currentMode: SW::Mode,
    activationCount: i32,
    currentMode: SW::Mode,
    api_AttackStatusRx: SW::AttackStatus,
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    (((In_currentMode == SW::Mode::Init) &&
      !(GumboLib::isAttack_spec(api_AttackStatusRx) || GumboLib::isAttack_spec(api_AttackStatusTx))) &&
      (activationCount >= 10i32)) ==>
      (currentMode == SW::Mode::Normal)
  }

  /** compute guarantee CR01_MM_StayNormal
    *   ModeManager_Req_StayNormal: in Normal with no attack, remain in Normal.
    */
  pub open spec fn compute_spec_CR01_MM_StayNormal_guarantee(
    In_currentMode: SW::Mode,
    currentMode: SW::Mode,
    api_AttackStatusRx: SW::AttackStatus,
    api_AttackStatusTx: SW::AttackStatus) -> bool
  {
    ((In_currentMode == SW::Mode::Normal) &&
      !(GumboLib::isAttack_spec(api_AttackStatusRx) || GumboLib::isAttack_spec(api_AttackStatusTx))) ==>
      (currentMode == SW::Mode::Normal)
  }

  /** compute guarantee CR01_MM_Broadcast
    *   ModeManager_Req_Broadcast: the mode DataPort output equals the post-transition mode state.
    */
  pub open spec fn compute_spec_CR01_MM_Broadcast_guarantee(
    currentMode: SW::Mode,
    api_CurrentMode: SW::Mode) -> bool
  {
    api_CurrentMode == currentMode
  }
}

} // verus!
